import pathlib,base64,hashlib,json
H=pathlib.Path('/home/ubuntu/rca/T-033')
files={'scripts/session6-002/accounted_worker.py': '', 'scripts/session6-002/bocpd_core.py': '', 'scripts/session6-002/bocpd_delay.py': '', 'scripts/session6-002/channel_context.py': '', 'scripts/session6-002/common.py': '', 'scripts/session6-002/fixtures.py': '', 'scripts/session6-002/job.sh': '', 'scripts/session6-002/nsigma_delay.py': '', 'scripts/session6-002/observe.py': '', 'scripts/session6-002/pins.json': ''}
for rel,data in files.items():
 p=(H/rel).resolve();assert p.is_relative_to(H);p.parent.mkdir(parents=True,exist_ok=True);b=base64.b64decode(data)
 if p.exists():assert p.read_bytes()==b,'Refuse different existing file'
 else:p.open('xb').write(b)
 assert hashlib.sha256(p.read_bytes()).hexdigest()==hashlib.sha256(b).hexdigest()
print(json.dumps({'status':'PASS','files':{r:{'sha256':hashlib.sha256(base64.b64decode(b)).hexdigest(),'bytes':len(base64.b64decode(b))} for r,b in files.items()}}))
